using Crucible.Assets;

namespace Crucible.Render;

/// <summary>
/// A texture parameter of a material (ADR 0052), as Slang's
/// <c>TextureSlot</c>: the texture's slot in the resource heap
/// (<see cref="RenderAssets.TextureDescriptor"/>), 0 for none.
/// </summary>
public struct TextureSlot
{
    public uint Index;
}

/// <summary>
/// A material type's parameters, generated by the Shader importer from a
/// material shader (ADR 0052) into the game's <c>Code/Generated/Materials/</c>.
/// </summary>
public interface IMaterialData
{
    /// <summary>The material shader's asset ID.</summary>
    static abstract AssetId ShaderId { get; }

    /// <summary>The Slang type's name.</summary>
    static abstract string TypeName { get; }
}
